<?php

declare(strict_types=1);
namespace SyntaxDevTeam\Cms\Modules\EventCalendar;
use SyntaxDevTeam\Cms\Core\ContentRenderer;

final class EventDiscordPayload
{
    public static function text(string $value,int $limit): string
    {
        $html=(new ContentRenderer())->render($value,'markdown');
        // HTML list markers are generated by browsers, so strip_tags loses them.
        $document = new \DOMDocument();
        $previous = libxml_use_internal_errors(true);
        try {
            $document->loadHTML('<?xml encoding="UTF-8"><div>' . $html . '</div>', LIBXML_NONET | LIBXML_NOERROR | LIBXML_NOWARNING);
        } finally {
            libxml_clear_errors();
            libxml_use_internal_errors($previous);
        }
        $walk = static function (\DOMNode $node, int $depth = 0) use (&$walk): string {
            if ($node instanceof \DOMText) return $node->textContent;
            $tag = strtolower($node->nodeName);
            if ($tag === 'br') return "\n";
            if (in_array($tag, ['ol', 'ul'], true)) {
                $result = "\n";
                $number = 0;
                foreach ($node->childNodes as $child) {
                    if ($child->nodeName !== 'li') continue;
                    $number++;
                    $body = '';
                    foreach ($child->childNodes as $part) $body .= $walk($part, $depth + 1);
                    $marker = $tag === 'ol' ? $number . '. ' : '• ';
                    $result .= str_repeat('  ', $depth) . $marker . trim($body) . "\n";
                }
                return $result;
            }
            $result = '';
            foreach ($node->childNodes as $child) $result .= $walk($child, $depth);
            return $result . (in_array($tag, ['p', 'div', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'blockquote', 'pre', 'tr'], true) ? "\n" : '');
        };
        $plain = trim(preg_replace('/\n{3,}/', "\n\n", $walk($document)) ?? '');
        return mb_strlen($plain) > $limit
            ? rtrim(mb_substr($plain, 0, $limit - 1)) . '…'
            : $plain;
    }
    public static function build(string $channel,array $event,?array $task,EventNotificationConfig $config,bool $test=false): array
    {
        $public=$channel==='public';$label=$test?'PRZYKŁADOWY KOMUNIKAT • TEST':($public?'WYDARZENIA SPOŁECZNOŚCI':'ZADANIA ADMINISTRACJI');
        if($test){$event=['id'=>0,'public_title'=>'Wieczór pod rozgwieżdżonym niebem','title'=>'Przygotowanie wieczoru społeczności','summary'=>'Wspólna przygoda, konkurs kreatywności i nagrody. Spotkajmy się na serwerze!','description'=>'Zapraszamy na wyjątkowe spotkanie naszej społeczności.','starts_at'=>gmdate('Y-m-d H:i:s',time()+86400),'ends_at'=>gmdate('Y-m-d H:i:s',time()+93600),'location'=>'Plac festiwalowy','rules'=>'Dobra zabawa i szacunek do innych graczy.','rewards'=>'Pamiątkowe nagrody dla uczestników.'];$task=['id'=>0,'title'=>'Przygotuj trasę i dekoracje','description'=>'Sprawdź punkty kontrolne, oświetlenie i gotowość placu festiwalowego.','due_at'=>gmdate('Y-m-d H:i:s',time()+82800),'assignee_name'=>'Przykładowy organizator','status'=>'todo'];}
        $url=$config->url($test?($public?'/events':'/admin/events'):($public?'/events/view?id='.$event['id']:'/admin/events?id='.$event['id'].'&tab=tasks&task='.(int)($task['id']??0)));
        $title=$public?$event['public_title']:($task['title']??'Zadanie zespołu');
        $embed=['author'=>['name'=>$label],'title'=>($test?'[TEST] ':'').(self::text($title,180)?:($public?'Wydarzenie społeczności':'Zadanie zespołu')),'url'=>$url,'color'=>$public?0xD246CB:0x8B71D9,'description'=>self::text($public?($event['summary']?:$event['description']):($task['description']??''),1500),'fields'=>[],'footer'=>['text'=>$test?'Dane fikcyjne • Ten test nie tworzy wydarzenia ani zadania.':'miniPORTAL • '.($public?'Dołącz do wspólnej historii':'Wewnętrzna organizacja wydarzenia')],'timestamp'=>gmdate('Y-m-d\TH:i:s\Z')];
        if($public){
            $start=strtotime($event['starts_at'].' UTC');$end=strtotime($event['ends_at'].' UTC');
            $embed['fields']=[['name'=>'Rozpoczęcie','value'=>'<t:'.$start.':F>','inline'=>true],['name'=>'Zakończenie','value'=>'<t:'.$end.':F>','inline'=>true],['name'=>'Miejsce','value'=>self::text($event['location']?:'Na serwerze',180),'inline'=>false]];
            foreach(['rules'=>'Zasady udziału','rewards'=>'Nagrody'] as $key=>$name)if(($event[$key]??'')!=='')$embed['fields'][]=['name'=>$name,'value'=>self::text($event[$key],1024)?:'Szczegóły na stronie','inline'=>false];
            if($config->image()!=='')$embed['image']=['url'=>$config->image()];
        }else{
            $embed['fields']=[['name'=>'Wydarzenie','value'=>self::text($event['title'],180),'inline'=>false],['name'=>'Odpowiedzialna osoba','value'=>self::text($task['assignee_name']??'Przypisana osoba',100),'inline'=>true],['name'=>'Stan','value'=>EventInput::TASKS[$task['status']]??'Do zrobienia','inline'=>true]];
            if($task['due_at'])$embed['fields'][]=['name'=>'Termin wykonania','value'=>'<t:'.strtotime($task['due_at'].' UTC').':F>','inline'=>false];
        }
        if($embed['description']==='')unset($embed['description']);
        $embed['fields'][]=['name'=>$public?'Wszystkie szczegóły':'Otwórz plan i zadanie','value'=>'['.($public?'Przejdź do wydarzenia':'Panel administracji').']('.$url.')','inline'=>false];
        return ['username'=>'Kalendarz wydarzeń','allowed_mentions'=>['parse'=>[]],'embeds'=>[$embed]];
    }
}
